export type GetNotesInput = { q: string }
export type GetNotesResponse = { items: { id: number; title: string; updatedAt?: string }[] }
export async function getNotes(input: GetNotesInput, signal?: AbortSignal): Promise<GetNotesResponse> {
  const url = new URL("/api/notes", "https://notes.example")
  url.searchParams.set("q", String(input.q))
  const response = await fetch(url, {
    method: "GET",
    signal,
    headers: {
      accept: 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error("GET /api/notes failed" + ` (${response.status})`)
  }
  return (await response.json()) as GetNotesResponse
}

export type GetNoteResponse = { id: number; title: string; updatedAt?: string }
export async function getNote(id: number, signal?: AbortSignal): Promise<GetNoteResponse> {
  const url = new URL(`/api/notes/${encodeURIComponent(String(id))}`, "https://notes.example")
  const response = await fetch(url, { method: "GET", signal })
  if (!response.ok) {
    throw new Error("GET /api/notes/{id} failed" + ` (${response.status})`)
  }
  return (await response.json()) as GetNoteResponse
}

export type CreateNoteInput = { title: string }
export type CreateNoteResponse = { id: number; title: string }
export async function createNote(input: CreateNoteInput, signal?: AbortSignal): Promise<CreateNoteResponse> {
  const url = new URL("/api/notes", "https://notes.example")
  const response = await fetch(url, {
    method: "POST",
    signal,
    headers: { "content-type": "application/json" },
    body: JSON.stringify(input),
  })
  if (!response.ok) {
    throw new Error("POST /api/notes failed" + ` (${response.status})`)
  }
  return (await response.json()) as CreateNoteResponse
}
